{{ config(
            materialized='table',
                post_hook={
                    "sql": "create or replace table snitch_db.maplemonk.pnl_data_category_level as WITH shopify_cancellations AS ( SELECT order_timestamp::DATE AS date, \'Shopify\' AS type, sku_group, 0 AS gross_sales, 0 AS gross_quantity, 0 AS discount_amount, NULL AS cost_price, quantity AS cancel_quantity, 0 AS return_quantity, 0 AS specific_return_amount FROM fact_items_snitch WHERE order_status = \'CANCELLED\' AND order_timestamp::DATE >= \'2025-06-01\' ), store_cancellations AS ( SELECT order_date AS date, \'Store\' AS type, sku_group, 0 AS gross_sales, 0 AS gross_quantity, 0 AS discount_amount, NULL AS cost_price, shipping_quantity AS cancel_quantity, 0 AS return_quantity, 0 AS specific_return_amount FROM store_fact_items WHERE order_status = \'Cancelled\' AND order_date >= DATE \'2025-06-01\' ), sales_data AS ( SELECT date, type, sku_group, gross_sales, gross_quantity, discount_amount, cost_price, 0 AS cancel_quantity, 0 AS return_quantity, 0 AS specific_return_amount FROM horizontal_sales_categories WHERE type IN (\'Store\', \'Shopify\') AND date >= DATE \'2025-06-01\' ), shopify_returns AS ( SELECT order_date AS date, \'Shopify\' AS type, sku_group, 0 AS gross_sales, 0 AS gross_quantity, 0 AS discount_amount, NULL AS cost_price, 0 AS cancel_quantity, return_qty_real AS return_quantity, 0 AS specific_return_amount FROM return_fact_items WHERE reason <> \'not_returned\' AND order_date >= DATE \'2025-06-01\' ), marketplace_sales AS ( SELECT ORDER_DATE AS date, \'Marketplace\' AS type, sku_group, CASE WHEN UPPER(ORDER_STATUS) <> \'CANCELLED\' THEN SELLING_PRICE ELSE 0 END AS gross_sales, CASE WHEN UPPER(ORDER_STATUS) <> \'CANCELLED\' THEN SHIPPING_QUANTITY ELSE 0 END AS gross_quantity, CASE WHEN UPPER(ORDER_STATUS) <> \'CANCELLED\' THEN DISCOUNT ELSE 0 END AS discount_amount, NULL AS cost_price, CASE WHEN UPPER(ORDER_STATUS) = \'CANCELLED\' THEN SHIPPING_QUANTITY ELSE 0 END AS cancel_quantity, 0 AS return_quantity, 0 AS specific_return_amount FROM snitch_db.maplemonk.unicommerce_fact_items_intermediate WHERE address_line_1 != \'FLIPKART_B2B_CUSTOM\' AND TRIM(UPPER(marketPlace_mapped)) IN (\'AMAZON\', \'MYNTRA\', \'AJIO\', \'FLIPKART\', \'NYKAA.COM\', \'NYKAA_FASHION\') AND ORDER_DATE >= \'2025-06-01\' ), marketplace_returns AS ( SELECT ORDER_DATE AS date, \'Marketplace\' AS type, SKU_GROUP AS sku_group, 0 AS gross_sales, 0 AS gross_quantity, 0 AS discount_amount, NULL AS cost_price, 0 AS cancel_quantity, RETURN_QTY AS return_quantity, RETURN_AMOUNT AS specific_return_amount FROM snitch_db.maplemonk.marketplace_sales_returns WHERE RETURN_QTY > 0 AND ORDER_DATE >= \'2025-06-01\' ), combined_transactions AS ( SELECT * FROM sales_data UNION ALL SELECT * FROM shopify_cancellations UNION ALL SELECT * FROM store_cancellations UNION ALL SELECT * FROM shopify_returns UNION ALL SELECT * FROM marketplace_sales UNION ALL SELECT * FROM marketplace_returns ), raw_data AS ( SELECT a.date, a.type, a.gross_sales, a.gross_quantity, a.discount_amount, a.cancel_quantity, a.return_quantity, a.specific_return_amount, COALESCE(a.cost_price, bp.cost_price) AS cost_price, b.category, b.original_price, CASE WHEN a.date >= DATE \'2025-09-22\' THEN CASE WHEN COALESCE(b.original_price, 0) < 2500 THEN a.gross_sales * 0.05 ELSE a.gross_sales * 0.18 END ELSE CASE WHEN COALESCE(b.original_price, 0) < 1000 THEN a.gross_sales * 0.05 ELSE a.gross_sales * 0.12 END END AS tax_amount, COALESCE( CASE WHEN LOWER(a.sku_group) LIKE \'4mbg%\' THEN \'plus_size\' WHEN LOWER(a.sku_group) LIKE \'r4mbg%\' THEN \'plus_size\' WHEN LOWER(b.style) LIKE \'%luxe%\' THEN \'luxe\' WHEN LOWER(b.style) LIKE \'%core%\' THEN \'core\' WHEN LOWER(b.category) IN (\'perfumes\',\'accessories\',\'bags\',\'belts\',\'sunglasses\',\'shoes\',\'slip-ons\') THEN \'long_tail\' ELSE NULL END, CASE WHEN UPPER(a.sku_group) LIKE \'4MCSR%\' THEN \'core\' WHEN UPPER(a.sku_group) LIKE \'4MSWHC%\' THEN \'core\' WHEN UPPER(a.sku_group) LIKE \'4MSWC%\' THEN \'core\' WHEN UPPER(a.sku_group) LIKE \'4MSKC%\' THEN \'core\' WHEN UPPER(a.sku_group) LIKE \'4MCRD%\' THEN \'core\' WHEN UPPER(a.sku_group) LIKE \'4MCRT%\' THEN \'core\' WHEN UPPER(a.sku_group) LIKE \'4MLRT%\' THEN \'luxe\' WHEN UPPER(a.sku_group) LIKE \'4MLXT%\' THEN \'luxe\' WHEN UPPER(a.sku_group) LIKE \'4MLXD%\' THEN \'luxe\' WHEN UPPER(a.sku_group) LIKE \'4MTLD%\' THEN \'luxe\' WHEN UPPER(a.sku_group) LIKE \'4MBGSS%\' THEN \'plus_size\' WHEN UPPER(a.sku_group) LIKE \'4MBGSR%\' THEN \'plus_size\' WHEN UPPER(a.sku_group) LIKE \'4MBGST%\' THEN \'plus_size\' WHEN UPPER(a.sku_group) LIKE \'SH00%\' THEN \'long_tail\' WHEN UPPER(a.sku_group) LIKE \'4MBL%\' THEN \'long_tail\' WHEN UPPER(a.sku_group) LIKE \'4MHT%\' THEN \'long_tail\' WHEN UPPER(a.sku_group) LIKE \'4MCP%\' THEN \'long_tail\' WHEN UPPER(a.sku_group) LIKE \'4MBD%\' THEN \'long_tail\' WHEN UPPER(a.sku_group) LIKE \'SN%\' THEN \'long_tail\' WHEN UPPER(a.sku_group) LIKE \'SH%\' THEN \'long_tail\' WHEN UPPER(a.sku_group) LIKE \'4MSFC%\' THEN \'long_tail\' ELSE NULL END, \'Snitch\' ) AS l1_category FROM combined_transactions a LEFT JOIN product_journey b ON a.sku_group = b.sku_group LEFT JOIN base_product bp ON a.sku_group = bp.sku_group ) SELECT date, type, l1_category, category, SUM(gross_sales) AS gross_sales, SUM(gross_quantity * COALESCE(original_price, 0)) AS mrp_sales, SUM(cancel_quantity * COALESCE(original_price, 0)) AS cancellations, SUM( CASE WHEN type = \'Marketplace\' THEN specific_return_amount ELSE return_quantity * COALESCE(original_price, 0) END ) AS returns, SUM(discount_amount) AS discount_amount, SUM(tax_amount) AS tax_amount, SUM(gross_quantity * COALESCE(cost_price, 0)) AS cogs, CASE WHEN SUM(gross_sales) = 0 THEN 0 ELSE (SUM(gross_sales) - SUM(gross_quantity * COALESCE(cost_price, 0))) / SUM(gross_sales) END AS gross_margin_pct FROM raw_data GROUP BY 1, 2, 3, 4 ORDER BY date DESC, type, l1_category;",
                    "transaction": true
                }
            ) }}
            with sample_data as (

                select * from snitch_db.information_schema.databases
            ),
            
            final as (
                select * from sample_data
            )
            select * from final
            